1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.Regiao;
4	import com.loja.checkout.domain.clube.NivelClube;
5	import com.loja.checkout.domain.cupom.Cupom;
6	import com.loja.checkout.domain.entrega.ModalidadeEntrega;
7	import com.loja.checkout.domain.pagamento.FormaPagamento;
8	import com.loja.checkout.domain.pagamento.ResultadoPagamento;
9	import com.loja.checkout.dto.ItemRequest;
10	import com.loja.checkout.dto.PedidoRequest;
11	import com.loja.checkout.dto.ResumoResponse;
12	import com.loja.checkout.exception.CheckoutException;
13	import jakarta.annotation.PostConstruct;
14	import org.springframework.stereotype.Service;
15	
16	import java.math.BigDecimal;
17	import java.math.RoundingMode;
18	import java.util.List;
19	import java.util.Map;
20	import java.util.function.Function;
21	import java.util.stream.Collectors;
22	
23	@Service
24	public class ResumoService {
25	
26	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
27	
28	    private final Map<String, ModalidadeEntrega> modalidades;
29	    private final Map<String, Cupom> cupons;
30	    private final Map<String, NivelClube> niveis;
31	    private final Map<String, FormaPagamento> formasPagamento;
32	
33	    public ResumoService(List<ModalidadeEntrega> modalidades,
34	                         List<Cupom> cupons,
35	                         List<NivelClube> niveis,
36	                         List<FormaPagamento> formasPagamento) {
37	        this.modalidades = modalidades.stream()
38	                .collect(Collectors.toMap(ModalidadeEntrega::codigo, Function.identity()));
39	        this.cupons = cupons.stream()
40	                .collect(Collectors.toMap(Cupom::codigo, Function.identity()));
41	        this.niveis = niveis.stream()
42	                .collect(Collectors.toMap(NivelClube::codigo, Function.identity()));
43	        this.formasPagamento = formasPagamento.stream()
44	                .collect(Collectors.toMap(FormaPagamento::codigo, Function.identity()));
45	    }
46	
47	    public ResumoResponse calcular(PedidoRequest pedido) {
48	        validarItens(pedido.itens());
49	
50	        BigDecimal subtotal = calcularSubtotal(pedido.itens());
51	        BigDecimal pesoTotal = calcularPesoTotal(pedido.itens());
52	
53	        NivelClube nivel = buscar(niveis, pedido.nivelClube(), "NIVEL_CLUBE_INVALIDO");
54	        buscarRegiao(pedido.regiao());
55	        Regiao regiao = Regiao.valueOf(pedido.regiao());
56	
57	        ModalidadeEntrega entrega = buscar(modalidades, pedido.modalidadeEntrega(), "MODALIDADE_INVALIDA");
58	        if (!entrega.disponivel(pesoTotal)) {
59	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
60	        }
61	
62	        BigDecimal frete = nivel.freteGratis()
63	                ? ZERO
64	                : entrega.calcularFrete(pesoTotal);
65	
66	        BigDecimal descontoCupom = ZERO;
67	        if (pedido.cupom() != null && !pedido.cupom().isEmpty()) {
68	            Cupom cupom = buscar(cupons, pedido.cupom(), "CUPOM_INVALIDO");
69	            if (!cupom.aplicavel(pedido.itens(), subtotal)) {
70	                throw new CheckoutException("CUPOM_NAO_APLICAVEL");
71	            }
72	            descontoCupom = cupom.calcularDesconto(pedido.itens(), subtotal, frete);
73	        }
74	
75	        FormaPagamento pagamento = buscar(formasPagamento, pedido.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
76	        int parcelas = pedido.parcelas() != null ? pedido.parcelas() : 1;
77	        if (!pagamento.parcelasValidas(parcelas)) {
78	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
79	        }
80	
81	        BigDecimal seguro = arredondar(subtotal.multiply(regiao.getPercentualSeguro()));
82	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
83	
84	        if (!pagamento.disponivel(totalPedido)) {
85	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
86	        }
87	
88	        ResultadoPagamento resultado = pagamento.calcular(totalPedido, parcelas);
89	        BigDecimal ajuste = resultado.totalFinal().subtract(totalPedido);
90	        BigDecimal credito = arredondar(subtotal.multiply(nivel.percentualCashback()));
91	        boolean brinde = nivel.temBrinde(subtotal);
92	
93	        return new ResumoResponse(
94	                subtotal,
95	                descontoCupom,
96	                frete,
97	                entrega.prazoDias(),
98	                seguro,
99	                ajuste,
100	                resultado.totalFinal(),
101	                parcelas,
102	                resultado.valorParcela(),
103	                credito,
104	                brinde
105	        );
106	    }
107	
108	    private void validarItens(List<ItemRequest> itens) {
109	        if (itens == null || itens.isEmpty()) {
110	            throw new CheckoutException("PEDIDO_INVALIDO");
111	        }
112	        for (ItemRequest item : itens) {
113	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
114	                    || item.quantidade() == null || item.quantidade() <= 0
115	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
116	                throw new CheckoutException("PEDIDO_INVALIDO");
117	            }
118	        }
119	    }
120	
121	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
122	        BigDecimal subtotal = BigDecimal.ZERO;
123	        for (ItemRequest item : itens) {
124	            subtotal = subtotal.add(
125	                    item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
126	        }
127	        return arredondar(subtotal);
128	    }
129	
130	    private BigDecimal calcularPesoTotal(List<ItemRequest> itens) {
131	        BigDecimal peso = BigDecimal.ZERO;
132	        for (ItemRequest item : itens) {
133	            peso = peso.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
134	        }
135	        return peso;
136	    }
137	
138	    private void buscarRegiao(String codigo) {
139	        if (codigo == null || codigo.isEmpty()) {
140	            throw new CheckoutException("REGIAO_INVALIDA");
141	        }
142	        try {
143	            Regiao.valueOf(codigo);
144	        } catch (IllegalArgumentException e) {
145	            throw new CheckoutException("REGIAO_INVALIDA");
146	        }
147	    }
148	
149	    private <T> T buscar(Map<String, T> mapa, String codigo, String codigoErro) {
150	        if (codigo == null || codigo.isEmpty()) {
151	            throw new CheckoutException(codigoErro);
152	        }
153	        T resultado = mapa.get(codigo);
154	        if (resultado == null) {
155	            throw new CheckoutException(codigoErro);
156	        }
157	        return resultado;
158	    }
159	
160	    private BigDecimal arredondar(BigDecimal valor) {
161	        return valor.setScale(2, RoundingMode.HALF_EVEN);
162	    }
163	}
