1	package com.loja.checkout.domain.pagamento;
2	
3	import org.springframework.stereotype.Component;
4	
5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	import java.math.RoundingMode;
8	
9	@Component
10	public class Cartao implements FormaPagamento {
11	
12	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
13	    private static final int PARCELAS_SEM_JUROS = 3;
14	
15	    @Override
16	    public String codigo() {
17	        return "CARTAO";
18	    }
19	
20	    @Override
21	    public boolean parcelasValidas(int parcelas) {
22	        return parcelas >= 1 && parcelas <= 12;
23	    }
24	
25	    @Override
26	    public boolean disponivel(BigDecimal totalPedido) {
27	        return true;
28	    }
29	
30	    @Override
31	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
32	        if (parcelas <= PARCELAS_SEM_JUROS) {
33	            BigDecimal valorParcela = totalPedido.divide(
34	                    BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
35	            return new ResultadoPagamento(totalPedido, valorParcela);
36	        }
37	
38	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_MENSAL);
39	        BigDecimal potencia = umMaisTaxa.pow(parcelas, MathContext.DECIMAL128);
40	        BigDecimal denominador = BigDecimal.ONE.subtract(
41	                BigDecimal.ONE.divide(potencia, MathContext.DECIMAL128));
42	        BigDecimal valorParcela = totalPedido
43	                .multiply(TAXA_MENSAL)
44	                .divide(denominador, 2, RoundingMode.HALF_EVEN);
45	        BigDecimal totalFinal = valorParcela.multiply(BigDecimal.valueOf(parcelas));
46	        return new ResultadoPagamento(totalFinal, valorParcela);
47	    }
48	}
